def compare_versions(a, b):
    """
    Compare two semantic version strings.

    Returns:
        -1 if a < b
         0 if a == b
         1 if a > b
    """
    def parse(v):
        core, _, rest = v.partition('+')          # ignore build metadata
        core, _, pre = core.partition('-')       # separate pre-release
        major, minor, patch = map(int, core.split('.'))
        pre_ids = pre.split('.') if pre else []
        return major, minor, patch, pre_ids

    def compare_id(id1, id2):
        num1 = id1.isdigit()
        num2 = id2.isdigit()
        if num1 and num2:
            n1, n2 = int(id1), int(id2)
            if n1 < n2:
                return -1
            if n1 > n2:
                return 1
            return 0
        if num1 and not num2:
            return -1
        if not num1 and num2:
            return 1
        # both non-numeric
        if id1 < id2:
            return -1
        if id1 > id2:
            return 1
        return 0

    maj_a, min_a, pat_a, pre_a = parse(a)
    maj_b, min_b, pat_b, pre_b = parse(b)

    # Compare major, minor, patch
    if maj_a != maj_b:
        return -1 if maj_a < maj_b else 1
    if min_a != min_b:
        return -1 if min_a < min_b else 1
    if pat_a != pat_b:
        return -1 if pat_a < pat_b else 1

    # Compare pre-release
    if not pre_a and not pre_b:
        return 0
    if not pre_a:
        return 1
    if not pre_b:
        return -1

    for id_a, id_b in zip(pre_a, pre_b):
        cmp = compare_id(id_a, id_b)
        if cmp != 0:
            return cmp

    # All shared identifiers equal; shorter list is lower
    if len(pre_a) < len(pre_b):
        return -1
    if len(pre_a) > len(pre_b):
        return 1
    return 0
