class Scheduler:
    def __init__(self):
        self._tasks = {}          # name -> task dict
        self._order = 0           # incremental order counter
        self.errors = []          # list of (name, exception)

    def schedule(self, name, run_at, callback, every=None):
        if name in self._tasks:
            raise ValueError(f"Task with name '{name}' already scheduled")
        if every is not None:
            if not isinstance(every, (int, float)):
                raise ValueError("every must be a number")
            if every <= 0:
                raise ValueError("every must be greater than 0")
        self._tasks[name] = {
            'run_at': run_at,
            'callback': callback,
            'every': every,
            'order': self._order,
        }
        self._order += 1

    def cancel(self, name):
        return self._tasks.pop(name, None) is not None

    def pending(self):
        return sorted(
            [(t['run_at'], name) for name, t in self._tasks.items()],
            key=lambda x: (x[0], self._tasks[x[1]]['order'])
        )

    def run_due(self, now):
        # Snapshot of tasks to run
        due = sorted(
            [(name, t) for name, t in self._tasks.items() if t['run_at'] <= now],
            key=lambda x: (x[1]['run_at'], x[1]['order'])
        )
        run_names = []

        for name, task in due:
            # Skip if task was cancelled before running
            if name not in self._tasks:
                continue

            # Run the callback
            try:
                task['callback']()
            except Exception as exc:
                self.errors.append((name, exc))

            # After callback, check if task still exists (may have been cancelled)
            if name not in self._tasks:
                continue

            run_names.append(name)

            # Reschedule or remove
            if task['every'] is not None:
                # Advance run_at to the next time > now
                new_run_at = task['run_at']
                while new_run_at <= now:
                    new_run_at += task['every']
                self._tasks[name]['run_at'] = new_run_at
            else:
                # One-time task: remove
                self._tasks.pop(name, None)

        return run_names
